# This independent test oracle normalizes exact integer results while CPython
# performs source control flow and the actual sys/conversion protocols.
# Its admitted sources have no int shadowing or reflection on the test helpers.
REFERENCE = r"""
import ast,builtins,json,sys
source,filename,mode=sys.argv[1:]
mask=(1<<(64 if mode=='i64'else 128))-1 if mode!='bigint'else None
original_int=int
helper='_pytors_digits_reference_normalize'
def normalize(value):
 if mask is None or type(value)is not original_int:return value
 value&=mask
 return value if value<=(mask>>1)else value-mask-1
def convert(*args,**kwargs):return normalize(original_int(*args,**kwargs))
class Policy(ast.NodeTransformer):
 def wrapped(self,node):return ast.copy_location(ast.Call(ast.Name(helper,ast.Load()),[node],[]),node)
 def visit_Constant(self,node):return self.wrapped(node)if type(node.value)is original_int else node
 def visit_BinOp(self,node):return self.wrapped(self.generic_visit(node))
 def visit_UnaryOp(self,node):return self.wrapped(self.generic_visit(node))
 def visit_Call(self,node):return self.wrapped(self.generic_visit(node))
assert helper not in source
node=Policy().visit(ast.parse(source,filename));ast.fix_missing_locations(node)
namespace={'__name__':'__main__',helper:normalize,'int':convert}
try:exec(compile(node,filename,'exec'),namespace)
except BaseException as error:
 frames=[];trace=error.__traceback__
 while trace is not None:
  if trace.tb_frame.f_code.co_filename==filename:frames.append((str(trace.tb_lineno),trace.tb_frame.f_code.co_name))
  trace=trace.tb_next
 try:message=type(error).__name__+(': '+str(error)if str(error)else'')
 except BaseException:message=type(error).__name__+': <exception str() failed>'
 print(json.dumps({'message':message,'frames':frames}),file=sys.stderr);sys.exit(1)
"""

