@unittest.skipUnless(shutil.which('rustc'), 'rustc is required')
class IntegerDigitLimitExecutionTests(unittest.TestCase):
    def compare(self, source, inputs, modes, string_mode):
        filename = 'integer_digit_limits.py'
        with tempfile.TemporaryDirectory(prefix='pytors-digit-limits-') as directory:
            for integer in modes:
                expected = []
                for data in inputs:
                    result = subprocess.run([sys.executable, '-I', '-S', '-c',
                        REFERENCE, source, filename, integer], input=data,
                        capture_output=True, text=True, timeout=20)
                    expected.append((result.returncode, result.stdout,
                        json.loads(result.stderr) if result.returncode else None))
                with patch('py2fastrust.codegen.generate', side_effect=AssertionError('VM fallback')):
                    result = transpile(source, TranspileOptions(integer=integer,
                        filename=filename, license='none', string_mode=string_mode))
                self.assertTrue(result.success, result.diagnostics)
                self.assertEqual(result.backend, 'native')
                self.assertLess(len(result.rust_source.encode()), 512 * 1024)
                for marker in ('enum Value', 'enum Op', 'struct Runtime', 'struct PegParser'):
                    self.assertNotIn(marker, result.rust_source)
                rust = Path(directory) / (integer + '.rs')
                rust.write_text(result.rust_source)
                for optimized in (False, True):
                    binary = rust.with_suffix('.opt' if optimized else '.debug')
                    built = subprocess.run(['rustc', '--edition=2021',
                        *(['-O'] if optimized else []), str(rust), '-o', str(binary)],
                        capture_output=True, text=True, timeout=120)
                    self.assertEqual(built.returncode, 0, built.stderr)
                    for data, reference in zip(inputs, expected):
                        with self.subTest(integer=integer, optimized=optimized, input=data):
                            actual = subprocess.run([str(binary)], input=data,
                                capture_output=True, text=True, timeout=30,
                                env={**os.environ, 'PATH': '/no-python-runtime'})
                            self.assertEqual((actual.returncode, actual.stdout), reference[:2], actual.stderr)
                            if reference[2] is None:
                                self.assertEqual(actual.stderr, '')
                            else:
                                self.assertTrue(actual.stderr.endswith(reference[2]['message'] + '\n'), actual.stderr)
                                self.assertEqual(re.findall(r'File ".*?", line (\d+), in ([^\n]+)', actual.stderr),
                                                 [tuple(frame) for frame in reference[2]['frames']])


def _case(name):
    def test(self):
        self.compare(*CASES[name])
    return test


for _name in CASES:
    setattr(IntegerDigitLimitExecutionTests, 'test_' + _name, _case(_name))


class IntegerDigitLimitStateKernelTests(unittest.TestCase):
    def test_invalid_setters_leave_the_previous_shared_value(self):
        source = 'import sys\nsys.set_int_max_str_digits(640)\nprint(sys.get_int_max_str_digits())\n'
        with tempfile.TemporaryDirectory(prefix='pytors-digit-state-') as directory:
            for integer in ('i64', 'i128', 'bigint'):
                result = transpile(source, TranspileOptions(integer=integer, license='none'))
                self.assertTrue(result.success, result.diagnostics)
                number = 'Int::from_i128(value)' if integer == 'bigint' else 'value as NativeInt'
                kernel = '\n#[test] fn preserves_state_on_rejection(){let number=|value:i128|' + number + ';'
                kernel += 'assert_eq!(native_int_digit_limit(),4300);'
                kernel += 'native_set_int_digit_limit(&number(640)).unwrap();'
                kernel += 'for value in [-1,1,639,2147483648,-2147483649]{'
                kernel += 'assert!(native_set_int_digit_limit(&number(value)).is_err());'
                kernel += 'assert_eq!(native_int_digit_limit(),640);}'
                kernel += 'native_set_int_digit_limit(&number(2147483647)).unwrap();'
                kernel += 'assert_eq!(native_int_digit_limit(),2147483647);'
                kernel += 'native_set_int_digit_limit(&number(0)).unwrap();'
                kernel += 'assert_eq!(native_int_digit_limit(),0);}'
                rust = Path(directory) / (integer + '.rs')
                rust.write_text(result.rust_source + kernel)
                for optimized in (False, True):
                    binary = rust.with_suffix('.opt' if optimized else '.debug')
                    built = subprocess.run(['rustc','--edition=2021','--test',
                        *(['-O'] if optimized else []),str(rust),'-o',str(binary)],
                        capture_output=True,text=True,timeout=120)
                    self.assertEqual(built.returncode,0,built.stderr)
                    ran = subprocess.run([str(binary)],capture_output=True,text=True,timeout=30,
                        env={**os.environ,'PATH':'/no-python-runtime'})
                    self.assertEqual(ran.returncode,0,ran.stdout+ran.stderr)


class IntegerDigitLimitMetadataTests(unittest.TestCase):
    def test_unrelated_short_integer_program_does_not_retain_limit_state(self):
        result = transpile('value=int(input())\nprint(value+1)\n')
        self.assertTrue(result.success, result.diagnostics)
        self.assertNotIn('NATIVE_INT_DIGIT_LIMIT', result.rust_source)
        self.assertNotIn('native_int_digit_preflight', result.rust_source)

    def test_deferred_bigint_exception_payloads_are_named_boundaries(self):
        for name in ('plain_missing_key_boundary', 'plain_assert_payload_boundary',
                     'plain_exception_payload_boundary'):
            result = transpile(CASES[name][0], TranspileOptions(integer='bigint'))
            self.assertFalse(result.success)
            self.assertTrue(any(item.code == 'E006' and item.line > 0
                and 'deferred digit-limited exception payload' in item.message
                for item in result.diagnostics), result.diagnostics)

    def test_custom_container_callback_representation_is_not_silently_admitted(self):
        source = CUSTOM_CONTAINER
        for integer in ('i64', 'i128', 'bigint'):
            result = transpile(source, TranspileOptions(integer=integer))
            self.assertFalse(result.success)
            self.assertTrue(any(item.code == 'E006' and 'callback-safe digit-limited container display'
                in item.message for item in result.diagnostics), result.diagnostics)

    def test_source_index_conversion_is_a_positioned_protocol_boundary(self):
        for integer in ('i64', 'i128', 'bigint'):
            result = transpile(INDEX_PROTOCOL, TranspileOptions(integer=integer))
            self.assertFalse(result.success)
            self.assertTrue(any(item.code == 'E006' and '__index__' in item.message
                and item.line > 0 for item in result.diagnostics), result.diagnostics)


if __name__ == '__main__':
    unittest.main()
